                    {
                        value = property.GetValue(null);
                        return true;
                    }
                    if (PyClassDescriptors.TryReadSlot(property, slot, out value)) return true;
                }
                if (owner.GetField(name, DeclaredStatic) is FieldInfo field)
                { value = field.GetValue(null); return true; }
            }
            value = null;
            return false;
        }

