            if (FallbackAttributeMethod(instance, name) is MethodInfo getter)
                return Unwrapped(() => getter.Invoke(instance, [name]));
            throw MissingAttribute(instance, name);
        }

        static bool TryFallbackAttribute(object instance, string name, out object? value)
        {
            value = null;
            if (FallbackAttributeMethod(instance, name) is not MethodInfo getter) return false;
            try { value = Unwrapped(() => getter.Invoke(instance, [name])); return true; }
            catch (MissingMemberException) { return false; }
        }

        static MethodInfo? FallbackAttributeMethod(object instance, string name) =>
            PyArgs.Best(instance.GetType().GetMethods(InstanceMembers).Where(method => method.Name == "__getattr__"),
                [name], null, out _);

        /// <summary>A generic extension method closed over the receiver's element type (count&lt;T&gt;(this List&lt;T&gt;, T) for a List&lt;long&gt;).</summary>
        static MethodInfo? CloseFor(MethodInfo m, Type receiver)
        {
            if (!m.IsGenericMethodDefinition) return m;
            var typeArgs = m.GetGenericArguments();
            var p0 = m.GetParameters()[0].ParameterType;
            if (!p0.IsGenericType) return null;
            var def = p0.GetGenericTypeDefinition();
            bool Matches(Type type) => type.IsGenericType && type.GetGenericTypeDefinition() == def;
            Type? match = receiver;
            while (match != null && !Matches(match)) match = match.BaseType;
            match ??= receiver.GetInterfaces().FirstOrDefault(Matches);
            if (match == null) return null;
            Type[] pattern = p0.GetGenericArguments();
            Type[] actual = match.GetGenericArguments();
            var closed = new Type[typeArgs.Length];
            for (int i = 0; i < typeArgs.Length; i++)
            {
                int position = Array.IndexOf(pattern, typeArgs[i]);
                if (position < 0) return null;
                closed[i] = actual[position];
            }
            try { return m.MakeGenericMethod(closed); } catch (ArgumentException) { return null; }
        }

        static object? InvokeExtension(string name, List<MethodInfo> candidates, object self, object?[] args,
            IDictionary<string, object?>? keywords)
        {
            var method = PyArgs.Best(candidates, [self, .. args], keywords, out var call);
            if (method == null) throw PyArgs.NoFit(name, keywords, candidates);
            return Unwrapped(() => method.Invoke(null, call));
        }

        /// <summary>Python instances can acquire attributes, while CLR receivers keep their normal setter behavior.</summary>
        public static void __setattr_late(object? value, object? receiver, string name, Action<dynamic, dynamic> clrSet, bool freshEmptyDict = false)
        {
            if (receiver == null || receiver is Exception error && PyExceptionState.HasAttribute(error, name) ||
                (receiver as Type ?? receiver.GetType()).IsDefined(typeof(PySourceAttribute), false))
                SetAttribute(receiver, name, value, freshEmptyDict);
            else
                clrSet(receiver, value);
        }

        /// <summary>setattr(obj, name, value): a declared property or field (converted to its type), else an attribute kept beside the object.</summary>
        public static void setattr(object? o, string name, object? value) => SetAttribute(o, name, value, freshEmptyDict: false);

        static void SetAttribute(object? o, string name, object? value, bool freshEmptyDict)
        {
            if (o == null) throw MissingAttribute(null, name);
            if (o is Exception error && PyExceptionState.HasAttribute(error, name))
            {
                PyExceptionState.SetAttribute(error, name, value);
                return;
            }
            if (name == "__class__")
            {
                if (value is Type same && same == o.GetType()) return;
                throw new InvalidCastException("__class__ assignment requires a compatible object layout");
            }
            if (o is PyLocalClassInstance instance) { instance.Set(name, value); return; }
            if (o is PyLocalDataClass local) { local.Members[name] = value; return; }
            if (o is Type t)
            {
                if (PyMetaclasses.Set(t, name, value)) return;
                if (t.GetProperty(name, StaticMembers) is PropertyInfo sp && sp.CanWrite) { sp.SetValue(null, AttributeValue(value, sp.PropertyType, freshEmptyDict)); return; }
                if (t.GetField(name, StaticMembers) is FieldInfo sf && !sf.IsInitOnly) { sf.SetValue(null, AttributeValue(value, sf.FieldType, freshEmptyDict)); return; }
                if (PyClassDescriptors.SetAddedAttribute(t, name, value)) return;
                throw MissingAttribute(t, name, $"type object '{PyTypeName(t)}' has no attribute '{name}' (Typhon classes cannot gain attributes at run time)");
            }
            if (o is PyFunction pf)
            {
                switch (name)
                {
                    case "__name__": pf.__name__ = (string)value!; return;
                    case "__qualname__": pf.__qualname__ = (string)value!; return;
                    case "__doc__": pf.__doc__ = value; return;
                    case "__wrapped__": pf.__wrapped__ = value; return;
                    case "__module__": pf.__module__ = (string)value!; return;
                }
                (pf._attrs ??= new Dictionary<string, object?>())[name] = value;
                return;
            }
            var type = o.GetType();
            if (ClassProperty(type, name) is { } setter)
            {
                setter.__set__(o, value);
                return;
            }
            if (NamedProperty(type, name, InstanceMembers) is PropertyInfo p && p.CanWrite) { p.SetValue(o, AttributeValue(value, p.PropertyType, freshEmptyDict)); return; }
            if (type.GetField(name, InstanceMembers) is FieldInfo f && !f.IsInitOnly) { f.SetValue(o, AttributeValue(value, f.FieldType, freshEmptyDict)); return; }
            if (o is IPyInstanceAttributes attributes) attributes.SetAttribute(name, value);
            else new PyAttrDict(o)[name] = value;
        }

        public static void delattr(object? o, string name)
        {
            if (o is Typhon.Stdlib.types.CellType cell && name == "cell_contents")
            {
                cell.Clear();
                return;
            }
            if (o is MissingMemberException error && PyExceptionState.IsAttributeErrorMember(name))
            {
                PyExceptionState.SetAttribute(error, name, null);
                return;
            }
            if (o is PyModule module && module.__dict__.Remove(name)) return;
            if (o is PyLocalClassInstance instance && instance.Remove(name)) return;
            if (o is PyLocalDataClass local && local.Members.Remove(name)) return;
            if (o is Type annotated && name == "__doc__" && annotated.IsDefined(typeof(PySourceAttribute), false))
                throw new InvalidCastException($"cannot delete '__doc__' attribute of type '{PyTypeName(annotated)}'");
            if (o is Type type && PyClassDescriptors.DeleteSlot(type, name)) return;
            if (o is Type owner && PyClassDescriptors.DeleteAddedAttribute(owner, name)) return;
            if (o != null && ClassProperty(o.GetType(), name) is { } deleter)
            {
                deleter.__delete__(o);
                return;
            }
            if (o is IPyInstanceAttributes attributes && attributes.RemoveAttribute(name)) return;
            if (o != null && PyAttrDict.RemoveExtra(o, name)) return;
            if (o is PyFunction pf && pf._attrs != null && pf._attrs.Remove(name)) return;
            throw MissingAttribute(o, name, $"'{(o == null ? "NoneType" : PyTypeName(o.GetType()))}' object has no attribute '{name}' (or it is declared by its class)");
        }

        // A literal {} has no aliases. Construct it with the receiver's closed mapping type when the C# field requires one.
        static object? AttributeValue(object? value, Type type, bool freshEmptyDict)
        {
            if (freshEmptyDict && value is System.Collections.IDictionary { Count: 0 } &&
                !type.IsInstanceOfType(value) && type.IsGenericType)
            {
                var definition = type.GetGenericTypeDefinition();
                if (definition == typeof(OrderedDictionary<,>) || definition == typeof(IDictionary<,>) ||
                    definition == typeof(IReadOnlyDictionary<,>))
                    return typeof(Builtins).GetMethod(nameof(__newdict))!.MakeGenericMethod(type.GetGenericArguments()).Invoke(null, [0]);
                if (definition == typeof(Dictionary<,>)) return Activator.CreateInstance(type);
            }
            return ConvertTo(value, type);
        }

        static object? ConvertTo(object? v, Type t) =>
            v == null || t.IsInstanceOfType(v) || t == typeof(object) ? v
            : System.Convert.ChangeType(v, Nullable.GetUnderlyingType(t) ?? t, System.Globalization.CultureInfo.InvariantCulture);
    }
}
